SELECT * FROM ( SELECT
TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.LAST_UPDT_PNTTM DESC) AS RNUM, A.BASIC_CODE AS basicCode, A.BASIC_GROUP_NM AS basicGroupNm, A.BASIC_GROUP_CNT AS basicGroupCnt, A.LAST_UPDT_PNTTM AS lastUpdtPnttm, A.LAST_UPDUSR_ID AS lastUpdusrId FROM TB_BRODBASICGROUP A WHERE 1=1
AND A.BASIC_CODE LIKE CONCAT('%', #{BASIC_CODE}, '%')
AND A.BASIC_GROUP_NM LIKE CONCAT('%', #{basicGroupNm}, '%')
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

